// inside module M:
  type union U { integer f1, octetstring f2 } 
  template U m_u1 := {f1 := 1} 
  template U mw_u2 := {f2 := ?} 
  template U mw_u3 := ? 
  template U m_u4 := ({ f1 := 2 }, {f2 := 'AB'O }) 
  template U mw_u5 := ({ f2 := '12?'O }, { f2 := '*34'O length(2) }) 
  var boolean v_checkResult := ischosen(m_u1.f1) // returns true 
  v_checkResult := ischosen(m_u1.f2) // yields false 
  v_checkResult := ischosen(mw_u2.f1) // yields false 
  v_checkResult := ischosen(mw_u2.f2) // yields true 
  v_checkResult := ischosen(mw_u3.f1) // yields false 
  v_checkResult := ischosen(mw_u3.f2) // yields false
  v_checkResult := ischosen(m_u4.f1) // yields false 
  v_checkResult := ischosen(m_u4.f2) // yields false 
  v_checkResult := ischosen(mw_u5.f1) // yields false 
  v_checkResult := ischosen(mw_u5.f2) // yields true 
  type record R { U u optional }
  template R m_r1 := { omit }
  var boolean v_checkResult := ischosen(m_r1.u.f1) // yields false

type record MyRecord {
     MyUnion u optional 
  }
  template MyRecord m_myRecord := { u := m_myUnion }
  template MyRecord mw_myRecord := { u := mw_myUnion }
  template MyRecord m_myRecord2 := { u := omit }
  var boolean v_checkResult := isvalue(m_myRecord.u.ch1); // yields true
  v_checkResult := isvalue(mw_myRecord.u.ch1); // yields false
  v_checkResult := isvalue(mw_myRecord.u.ch2); // yields false
  v_checkResult := isvalue(m_myRecord.u.ch2); // yields false

